package rag

// TestRetrieveDefaultGolden pins the default behaviour of RAGService.Retrieve
// with a fixed table of scenarios. The expected outcomes live in
// testdata/retrieve_default.golden.json, which was generated by the code as it
// was BEFORE the E2 refactor (commit 07b53a4). If this test fails, the default
// path no longer behaves the way it did.
//
// The data file is regenerated only on purpose, with
//
//	go test ./common/rag -run TestRetrieveDefaultGolden -update-retrieval-golden
//
// and only following the rules in retrieval_legacy_test.go. The fakes mean this
// proves "same output, same calls to every dependency" and nothing about the
// quality of retrieval on a real index.

import (
	"bytes"
	"context"
	"encoding/json"
	"flag"
	"fmt"
	"os"
	"path/filepath"
	"testing"
	"time"
)

var updateRetrievalGolden = flag.Bool("update-retrieval-golden", false,
	"rewrite testdata/retrieve_default.golden.json from the CURRENT Retrieve; read retrieval_legacy_test.go before using")

const retrievalGoldenFile = "retrieve_default.golden.json"

func goldenScenarios() []retrievalScenario {
	var out []retrievalScenario
	base := func(name string, mutate func(*retrievalScenario)) {
		sc := retrievalScenario{
			Name: name, UserID: 73, Query: "如何设置 TTL", TopK: 5, Active: scenarioActive(3),
			Vector: scenarioRows(0, 40, 3, rowFlags{}), Lexical: scenarioRows(10, 40, 3, rowFlags{}),
		}
		if mutate != nil {
			mutate(&sc)
		}
		out = append(out, sc)
	}

	// A. Request validation and the context.
	for _, topK := range []int{-1, 0, 101, 1000} {
		topK := topK
		base(fmt.Sprintf("validation/topk=%d", topK), func(sc *retrievalScenario) { sc.TopK = topK })
	}
	base("validation/user=0", func(sc *retrievalScenario) { sc.UserID = 0 })
	base("validation/user=-5", func(sc *retrievalScenario) { sc.UserID = -5 })
	base("validation/query-empty", func(sc *retrievalScenario) { sc.Query = "" })
	base("validation/query-blank", func(sc *retrievalScenario) { sc.Query = "  \t\n " })
	base("validation/query-is-trimmed", func(sc *retrievalScenario) { sc.Query = "   TTL 设置  " })
	base("validation/nil-context", func(sc *retrievalScenario) { sc.NilContext = true })
	base("validation/topk=1-is-valid", func(sc *retrievalScenario) { sc.TopK = 1 })
	base("validation/topk=100-is-valid", func(sc *retrievalScenario) { sc.TopK = 100 })

	// B. Active documents.
	base("active/empty-list", func(sc *retrievalScenario) { sc.Active = []ActiveDocument{} })
	base("active/nil-list", func(sc *retrievalScenario) { sc.Active = nil })
	base("active/loader-error", func(sc *retrievalScenario) { sc.ActiveErr = errScenarioLoad })
	base("active/empty-doc-id", func(sc *retrievalScenario) { sc.Active = []ActiveDocument{{DocID: "", Version: 1}} })
	base("active/zero-version", func(sc *retrievalScenario) { sc.Active = []ActiveDocument{{DocID: "doc-0", Version: 0}} })
	base("active/single-document", func(sc *retrievalScenario) {
		sc.Active = scenarioActive(1)
		sc.Vector, sc.Lexical = scenarioRows(0, 10, 1, rowFlags{}), scenarioRows(5, 10, 1, rowFlags{})
	})

	// C. The embedder.
	base("embed/error", func(sc *retrievalScenario) { sc.Embed = embedError })
	base("embed/wrapped-cancel-live-context", func(sc *retrievalScenario) { sc.Embed = embedCanceled })
	base("embed/wrapped-cancel-cancelled-context", func(sc *retrievalScenario) { sc.Embed, sc.PreCancel = embedCanceled, true })
	base("embed/wrong-vector-count", func(sc *retrievalScenario) { sc.Embed = embedWrongCount })
	base("embed/wrong-dimension", func(sc *retrievalScenario) { sc.Embed = embedWrongDim })
	base("embed/nan-component", func(sc *retrievalScenario) { sc.Embed = embedNaN })
	base("embed/waits-then-deadline", func(sc *retrievalScenario) { sc.Embed, sc.Timeout = embedWait, 20*time.Millisecond })
	base("embed/waits-then-cancelled-context", func(sc *retrievalScenario) { sc.Embed, sc.PreCancel = embedWait, true })

	// D. The two searches.
	base("search/vector-error", func(sc *retrievalScenario) { sc.VectorErr = errScenarioVector })
	base("search/lexical-error", func(sc *retrievalScenario) { sc.LexicalErr = errScenarioLexical })
	base("search/both-error-vector-wins", func(sc *retrievalScenario) { sc.VectorErr, sc.LexicalErr = errScenarioVector, errScenarioLexical })
	base("search/vector-wrapped-cancel-cancelled-context", func(sc *retrievalScenario) {
		sc.VectorErr, sc.PreCancel = fmt.Errorf("vector wrapped: %w", context.Canceled), true
	})
	base("search/lexical-wrapped-cancel-cancelled-context", func(sc *retrievalScenario) {
		sc.LexicalErr, sc.PreCancel = fmt.Errorf("lexical wrapped: %w", context.Canceled), true
	})
	base("search/vector-wrapped-cancel-live-context", func(sc *retrievalScenario) {
		sc.VectorErr = fmt.Errorf("vector wrapped: %w", context.Canceled)
	})

	// E. Versions.
	base("version/stale-vector-rows", func(sc *retrievalScenario) { sc.Vector = scenarioRows(0, 40, 3, rowFlags{staleEvery: 7}) })
	base("version/stale-lexical-rows", func(sc *retrievalScenario) { sc.Lexical = scenarioRows(10, 40, 3, rowFlags{staleEvery: 7}) })
	base("version/row-of-inactive-document", func(sc *retrievalScenario) { sc.Vector = scenarioRows(0, 40, 4, rowFlags{}) })

	// F. Fusion without a reranker, across the candidate-depth boundaries.
	patterns := []struct {
		name  string
		build func(*retrievalScenario)
	}{
		{"overlap", func(sc *retrievalScenario) {
			sc.Vector, sc.Lexical = scenarioRows(0, 60, 3, rowFlags{}), scenarioRows(20, 60, 3, rowFlags{})
		}},
		{"vector-only", func(sc *retrievalScenario) { sc.Vector, sc.Lexical = scenarioRows(0, 60, 3, rowFlags{}), nil }},
		{"lexical-only", func(sc *retrievalScenario) { sc.Vector, sc.Lexical = nil, scenarioRows(0, 60, 3, rowFlags{}) }},
		{"duplicates-and-missing-keys", func(sc *retrievalScenario) {
			rows := scenarioRows(0, 12, 3, rowFlags{noKeyEvery: 4})
			sc.Vector = append(scenarioRows(0, 20, 3, rowFlags{noKeyEvery: 4}), rows...)
			sc.Lexical = append(scenarioRows(5, 20, 3, rowFlags{noKeyEvery: 4}), rows...)
		}},
		{"no-candidates", func(sc *retrievalScenario) { sc.Vector, sc.Lexical = nil, nil }},
	}
	for _, topK := range []int{1, 5, 8, 9, 30, 100} {
		for _, pattern := range patterns {
			topK, pattern := topK, pattern
			base(fmt.Sprintf("fusion/%s/topk=%d", pattern.name, topK), func(sc *retrievalScenario) {
				sc.TopK = topK
				pattern.build(sc)
			})
		}
	}

	// G. With a reranker: the topK <= 8 rule, the 24-candidate pool and every way the reranker can answer.
	for _, mode := range []rerankMode{rerankReverse, rerankTie, rerankMixed, rerankUnavailable, rerankFailure, rerankShort, rerankBadIndex, rerankDupIndex, rerankNaN} {
		for _, topK := range []int{1, 5, 8} {
			mode, topK := mode, topK
			base(fmt.Sprintf("rerank/%s/topk=%d", mode, topK), func(sc *retrievalScenario) { sc.Rerank, sc.TopK = mode, topK })
		}
	}
	for _, topK := range []int{9, 12, 30, 100} {
		topK := topK
		base(fmt.Sprintf("rerank/bypassed/topk=%d", topK), func(sc *retrievalScenario) { sc.Rerank, sc.TopK = rerankReverse, topK })
	}
	base("rerank/pool-smaller-than-24", func(sc *retrievalScenario) {
		sc.Rerank, sc.TopK = rerankReverse, 8
		sc.Vector, sc.Lexical = scenarioRows(0, 5, 3, rowFlags{}), nil
	})
	base("rerank/topk-larger-than-pool", func(sc *retrievalScenario) {
		sc.Rerank, sc.TopK = rerankReverse, 8
		sc.Vector, sc.Lexical = scenarioRows(0, 3, 3, rowFlags{}), scenarioRows(1, 3, 3, rowFlags{})
	})
	base("rerank/single-candidate", func(sc *retrievalScenario) {
		sc.Rerank, sc.TopK = rerankMixed, 5
		sc.Vector, sc.Lexical = scenarioRows(0, 1, 3, rowFlags{}), nil
	})
	base("rerank/no-candidates", func(sc *retrievalScenario) {
		sc.Rerank, sc.TopK = rerankReverse, 5
		sc.Vector, sc.Lexical = nil, nil
	})
	base("rerank/falls-back-to-raw-content", func(sc *retrievalScenario) {
		sc.Rerank, sc.TopK = rerankReverse, 5
		sc.Vector, sc.Lexical = scenarioRows(0, 40, 3, rowFlags{noEmbedEvery: 3}), scenarioRows(10, 40, 3, rowFlags{noEmbedEvery: 3})
	})
	base("rerank/empty-candidate-content", func(sc *retrievalScenario) {
		sc.Rerank, sc.TopK = rerankReverse, 5
		sc.Vector, sc.Lexical = scenarioRows(0, 10, 3, rowFlags{emptyContent: true}), nil
	})
	base("rerank/stale-candidate-in-pool", func(sc *retrievalScenario) {
		sc.Rerank, sc.TopK = rerankReverse, 5
		sc.Vector = scenarioRows(0, 40, 3, rowFlags{staleEvery: 5})
	})
	base("rerank/with-missing-keys", func(sc *retrievalScenario) {
		sc.Rerank, sc.TopK = rerankMixed, 8
		sc.Vector, sc.Lexical = scenarioRows(0, 30, 3, rowFlags{noKeyEvery: 3}), scenarioRows(10, 30, 3, rowFlags{noKeyEvery: 3})
	})
	return out
}

func TestRetrieveDefaultGolden(t *testing.T) {
	scenarios := goldenScenarios()
	seen := map[string]struct{}{}
	got := make([]retrievalGoldenRecord, 0, len(scenarios))
	for _, scenario := range scenarios {
		if _, duplicate := seen[scenario.Name]; duplicate {
			t.Fatalf("duplicate golden scenario name %q", scenario.Name)
		}
		seen[scenario.Name] = struct{}{}
		got = append(got, runRetrievalScenario(t, scenario, currentRetrieve).golden(scenario.Name))
	}
	encoded, err := json.MarshalIndent(got, "", "  ")
	if err != nil {
		t.Fatal(err)
	}
	encoded = append(encoded, '\n')
	path := filepath.Join("testdata", retrievalGoldenFile)
	if *updateRetrievalGolden {
		if err := os.MkdirAll("testdata", 0o755); err != nil {
			t.Fatal(err)
		}
		if err := os.WriteFile(path, encoded, 0o644); err != nil {
			t.Fatal(err)
		}
		t.Logf("rewrote %s with %d scenarios", path, len(got))
		return
	}
	want, err := os.ReadFile(path)
	if err != nil {
		t.Fatalf("read %s: %v (generate it with -update-retrieval-golden on the pre-refactor code)", path, err)
	}
	// A Windows checkout with core.autocrlf rewrites the data file with CRLF; the content is the same.
	want = bytes.ReplaceAll(want, []byte("\r\n"), []byte("\n"))
	if bytes.Equal(want, encoded) {
		return
	}
	var wantRecords []retrievalGoldenRecord
	if err := json.Unmarshal(want, &wantRecords); err != nil {
		t.Fatalf("parse %s: %v", path, err)
	}
	wantByName := make(map[string]string, len(wantRecords))
	for _, record := range wantRecords {
		data, _ := json.MarshalIndent(record, "", "  ")
		wantByName[record.Name] = string(data)
	}
	reported := 0
	for _, record := range got {
		data, _ := json.MarshalIndent(record, "", "  ")
		expected, known := wantByName[record.Name]
		switch {
		case !known:
			t.Errorf("scenario %q is not in the golden data", record.Name)
		case expected != string(data):
			if reported < 3 {
				t.Errorf("scenario %q changed.\n--- golden\n%s\n--- now\n%s", record.Name, truncateForReport(expected), truncateForReport(string(data)))
			} else {
				t.Errorf("scenario %q changed", record.Name)
			}
			reported++
		}
		delete(wantByName, record.Name)
	}
	for name := range wantByName {
		t.Errorf("golden scenario %q is no longer produced", name)
	}
}

// TestRetrieveGoldenScenariosCoverTheBranches keeps the fixed table honest: it
// fails if the scenarios stop reaching every retrieval outcome and every
// reranker outcome, so the data file cannot quietly become a weak guard.
func TestRetrieveGoldenScenariosCoverTheBranches(t *testing.T) {
	scenarios := goldenScenarios()
	if len(scenarios) < 90 {
		t.Fatalf("only %d golden scenarios, want at least 90", len(scenarios))
	}
	reached := map[string]bool{}
	required := []string{
		"knowledge_retrieval_total{status=complete,reason=none}",
		"knowledge_retrieval_total{status=no_evidence,reason=no_candidate}",
		"knowledge_retrieval_total{status=unavailable,reason=embedding_unavailable}",
		"knowledge_retrieval_total{status=unavailable,reason=vector_unavailable}",
		"knowledge_retrieval_total{status=unavailable,reason=lexical_unavailable}",
		"knowledge_retrieval_total{status=unavailable,reason=document_metadata_unavailable}",
		"knowledge_retrieval_total{status=failed,reason=invalid_result}",
		"knowledge_rerank_total{status=applied}",
		"knowledge_rerank_total{status=fallback}",
		"knowledge_rerank_total{status=failed}",
		"knowledge_rerank_total{status=bypassed}",
		"knowledge_candidate_total{match_kind=vector}",
		"knowledge_candidate_total{match_kind=lexical}",
		"knowledge_candidate_total{match_kind=hybrid}",
	}
	for _, scenario := range scenarios {
		record := runRetrievalScenario(t, scenario, currentRetrieve)
		for key := range record.Counters {
			reached[key] = true
		}
	}
	for _, key := range required {
		if !reached[key] {
			t.Errorf("no golden scenario reaches %s", key)
		}
	}
}

func truncateForReport(text string) string {
	const limit = 1800
	if len(text) <= limit {
		return text
	}
	return text[:limit] + "\n... (truncated)"
}
